import{_ as a,o as r,c as o,O as l}from"./chunks/framework.db831a78.js";const p=JSON.parse('{"title":"设计原则与架构演进","description":"","frontmatter":{},"headers":[],"relativePath":"backend/系统设计/设计原则与架构演进.md","filePath":"backend/系统设计/设计原则与架构演进.md","lastUpdated":1788941422000}'),e={name:"backend/系统设计/设计原则与架构演进.md"};function d(n,t,s,i,h,u){return r(),o("div",null,t[0]||(t[0]=[l(`<h1 id="设计原则与架构演进" tabindex="-1">设计原则与架构演进 <a class="header-anchor" href="#设计原则与架构演进" aria-label="Permalink to &quot;设计原则与架构演进&quot;">​</a></h1><blockquote><p>把单一职责、开闭、依赖倒置等设计原则翻译到架构层，理清单体到集群、微服务、平台化的演进驱动与代价，并识别过度设计信号。</p></blockquote><hr><h2 id="一、设计原则的架构层解读" tabindex="-1">一、设计原则的架构层解读 <a class="header-anchor" href="#一、设计原则的架构层解读" aria-label="Permalink to &quot;一、设计原则的架构层解读&quot;">​</a></h2><h3 id="_1-1-从代码原则到架构原则" tabindex="-1">1.1 从代码原则到架构原则 <a class="header-anchor" href="#_1-1-从代码原则到架构原则" aria-label="Permalink to &quot;1.1 从代码原则到架构原则&quot;">​</a></h3><p>代码层的 SOLID 原则讨论的是&quot;类与接口怎么设计&quot;，架构层讨论的是&quot;模块、服务、系统边界怎么切&quot;。同一个名字，尺度不同，判断方法也不同：</p><table><thead><tr><th>原则</th><th>代码层语义</th><th>架构层语义</th></tr></thead><tbody><tr><td>单一职责 SRP</td><td>一个类只有一个引起它变化的原因</td><td>一个模块/服务只承担一条变化轴上的职责，某个业务变更只应触及一个服务</td></tr><tr><td>开闭原则 OCP</td><td>对扩展开放、对修改封闭（继承/多态/策略）</td><td>通过扩展点（SPI、事件、插件、网关路由）演进，而不是改既有服务内部</td></tr><tr><td>依赖倒置 DIP</td><td>依赖抽象而非具体实现</td><td>上层不依赖下层实现：领域层依赖仓储接口、调用方依赖服务契约，用防腐层隔离外部系统</td></tr><tr><td>接口隔离 ISP</td><td>客户端不依赖不需要的接口</td><td>服务契约按消费方裁剪，避免&quot;大而全&quot;的共享 API 造成的强耦合</td></tr><tr><td>里氏替换 LSP</td><td>子类可替换父类</td><td>服务提供方的契约演进必须兼容存量消费者，版本兼容是架构层的 LSP</td></tr></tbody></table><p>判断尺度：代码层看&quot;一个类&quot;，架构层看&quot;一次变更的波及面&quot;。架构设计的高频追问应当是&quot;这条需求要改几个服务、几个模块&quot;——数量越少，SRP 在架构层越成立。</p><h3 id="_1-2-单一职责在架构层的两种切法" tabindex="-1">1.2 单一职责在架构层的两种切法 <a class="header-anchor" href="#_1-2-单一职责在架构层的两种切法" aria-label="Permalink to &quot;1.2 单一职责在架构层的两种切法&quot;">​</a></h3><ul><li>按<strong>技术层次</strong>切：网关层、应用层、数据层各司其职，纵向复用基础设施；</li><li>按<strong>业务能力</strong>切：订单、库存、支付各自成域，横向隔离变化。</li></ul><p>真实系统两者叠加，先按业务能力纵切（变化隔离），再在每个能力内部按层次横切（关注点分离）。常见错误是只按层次切（如&quot;Controller 工程&quot;&quot;DAO 工程&quot;），导致一次业务改动要横穿多个工程发布。</p><h3 id="_1-3-开闭原则的架构实现手法" tabindex="-1">1.3 开闭原则的架构实现手法 <a class="header-anchor" href="#_1-3-开闭原则的架构实现手法" aria-label="Permalink to &quot;1.3 开闭原则的架构实现手法&quot;">​</a></h3><p>架构层&quot;不修改就扩展&quot;主要靠四类机制：</p><ol><li><strong>插件/SPI</strong>：预留扩展点，新实现通过注册接入，不改核心代码；</li><li><strong>事件驱动</strong>：核心流程只发领域事件，新增消费者（短信、审计、风控）不触碰核心链路；</li><li><strong>策略路由</strong>：网关按规则路由到新老实现，实现新旧能力切换不修改调用方；</li><li><strong>数据驱动配置</strong>：把易变规则外置到配置中心或规则引擎。</li></ol><p>反模式：为了&quot;扩展&quot;提前抽象出三层接口、五个工厂，但唯一实现只有一个——这属于把开闭原则用成了过度设计（见第三章）。</p><h3 id="_1-4-依赖倒置与防腐层" tabindex="-1">1.4 依赖倒置与防腐层 <a class="header-anchor" href="#_1-4-依赖倒置与防腐层" aria-label="Permalink to &quot;1.4 依赖倒置与防腐层&quot;">​</a></h3><p>架构层最常见的依赖倒置应用是<strong>领域层不依赖基础设施</strong>：领域代码只依赖仓储接口，MySQL/Redis 的实现细节由基础设施层提供。向外对接第三方系统（短信、风控、旧系统）时用**防腐层（ACL）**包一层，把外部模型的&quot;方言&quot;翻译成内部领域语言，避免外部模型污染核心模型。</p><p>典型错误是 Controller 直接操作 DAO、Service 直接 new 具体客户端，导致领域逻辑与中间件 API 缠绕，中间件升级即全量返工。</p><h3 id="_1-5-原则冲突时的取舍顺序" tabindex="-1">1.5 原则冲突时的取舍顺序 <a class="header-anchor" href="#_1-5-原则冲突时的取舍顺序" aria-label="Permalink to &quot;1.5 原则冲突时的取舍顺序&quot;">​</a></h3><p>原则之间会打架，按以下优先级取舍可减少纠结：</p><ol><li>先保<strong>可用性与可运维性</strong>（架构首先要能活下来）；</li><li>再保<strong>变化隔离</strong>（SRP/OCP，把最常变化的业务隔到最小边界）；</li><li>最后才优化<strong>代码复用</strong>（复用是手段不是目标，跨边界强行复用往往制造耦合）。</li></ol><p>记住：架构层&quot;复用&quot;的优先级低于&quot;隔离&quot;。为了复用把两个变化频率不同的模块捏在一起，等于同时违反 SRP 与 OCP。</p><h3 id="_1-6-架构原则速查表" tabindex="-1">1.6 架构原则速查表 <a class="header-anchor" href="#_1-6-架构原则速查表" aria-label="Permalink to &quot;1.6 架构原则速查表&quot;">​</a></h3><table><thead><tr><th>场景信号</th><th>该用的原则</th><th>反例</th></tr></thead><tbody><tr><td>一次改单影响多个服务</td><td>SRP</td><td>把用户与订单逻辑放同一服务</td></tr><tr><td>新接入一个外部渠道要改核心代码</td><td>OCP / 防腐层</td><td>支付渠道逻辑散落在订单流程各处</td></tr><tr><td>领域代码混着 MyBatis/SQL</td><td>DIP</td><td>Service 直接注入 Mapper</td></tr><tr><td>上游接口一改下游全炸</td><td>契约/版本管理、LSP</td><td>共享 DTO 随意删字段</td></tr><tr><td>所有消费方被迫传一堆无用参数</td><td>ISP</td><td>一个万能 API 服务所有客户端</td></tr></tbody></table><hr><h2 id="二、架构演进路线" tabindex="-1">二、架构演进路线 <a class="header-anchor" href="#二、架构演进路线" aria-label="Permalink to &quot;二、架构演进路线&quot;">​</a></h2><h3 id="_2-1-演进驱动因素总览" tabindex="-1">2.1 演进驱动因素总览 <a class="header-anchor" href="#_2-1-演进驱动因素总览" aria-label="Permalink to &quot;2.1 演进驱动因素总览&quot;">​</a></h3><p>架构不会自发变复杂，驱动演进的通常是四类力量：</p><table><thead><tr><th>力量</th><th>典型信号</th><th>引发的结果</th></tr></thead><tbody><tr><td>业务复杂度上升</td><td>模块间互相依赖、改一处崩多处</td><td>模块化/服务化</td></tr><tr><td>流量上升</td><td>CPU 打满、DB 连接耗尽</td><td>集群化、加缓存、读写分离</td></tr><tr><td>团队规模上升</td><td>提交冲突频繁、发布互相阻塞</td><td>按团队边界拆分、服务化</td></tr><tr><td>部署与可靠性诉求</td><td>发布即全停、故障全波及</td><td>独立部署、故障隔离、灰度</td></tr></tbody></table><p>演进的正确姿势是&quot;信号驱动&quot;而非&quot;潮流驱动&quot;：只有出现上面某一列的信号，才考虑进入下一形态。</p><h3 id="_2-2-阶段一-单体架构" tabindex="-1">2.2 阶段一：单体架构 <a class="header-anchor" href="#_2-2-阶段一-单体架构" aria-label="Permalink to &quot;2.2 阶段一：单体架构&quot;">​</a></h3><ul><li><strong>形态</strong>：一个进程、一个数据库、一套代码库，模块按 package 分层。</li><li><strong>优势</strong>：开发简单、调试直观、事务天然、部署运维成本最低，是 0 到 1 阶段的最优解。</li><li><strong>代价</strong>：代码库膨胀后构建慢、启动慢；模块间只能靠约定约束边界（package 边界可被轻易绕过）；任何变更都是全量回归；水平扩展只能整机复制，DB 成为单点。</li><li><strong>适用边界</strong>：团队 10 人内、业务逻辑以简单 CRUD 为主、日活量级小。</li></ul><p>单体架构本身不是错误，错误的是&quot;业务已经长成多个域，却还硬塞在一个进程里&quot;。</p><h3 id="_2-3-阶段二-集群化与纵向分层" tabindex="-1">2.3 阶段二：集群化与纵向分层 <a class="header-anchor" href="#_2-3-阶段二-集群化与纵向分层" aria-label="Permalink to &quot;2.3 阶段二：集群化与纵向分层&quot;">​</a></h3><p>流量先于业务复杂度到来时的首选演进，<strong>不拆服务也能抗量</strong>：</p><ol><li><strong>无状态化</strong>：Session 外置到 Redis，任何实例可被替换；</li><li><strong>反向代理 + 负载均衡</strong>：Nginx 分发流量，多实例水平扩展；</li><li><strong>缓存前置</strong>：Redis 挡住热点读，降低 DB 压力；</li><li><strong>DB 读写分离</strong>：主库写、从库读；</li><li><strong>动静分离</strong>：静态资源上 CDN。</li></ol><ul><li><strong>优势</strong>：架构改动小，收益立竿见影，仍是单体代码库。</li><li><strong>代价</strong>：有状态逻辑（定时任务、本地缓存、文件存储）需要改造；分布式下的事务与锁问题初现（需要分布式锁、最终一致性）；运维对象从 1 个进程变成 N 个实例加一堆中间件。</li><li><strong>关键判断</strong>：如果这个阶段的问题只是&quot;性能不够&quot;，不要用拆微服务来解决——那是用复杂度换性能的亏本生意。</li></ul><h3 id="_2-4-阶段三-服务化与微服务" tabindex="-1">2.4 阶段三：服务化与微服务 <a class="header-anchor" href="#_2-4-阶段三-服务化与微服务" aria-label="Permalink to &quot;2.4 阶段三：服务化与微服务&quot;">​</a></h3><ul><li><strong>驱动</strong>：业务复杂度和团队规模信号（模块耦合、发布阻塞、单点故障波及全站），而不是流量。</li><li><strong>形态</strong>：按业务能力/子域拆成独立可部署服务，服务间通过 REST/gRPC 或 MQ 协作。</li><li><strong>优势</strong>：独立开发、独立部署、独立伸缩、故障隔离、技术栈可选。</li><li><strong>代价</strong>（必须清醒认识的账）： <ul><li>基础设施成本：注册中心、网关、配置中心、链路追踪、日志聚合缺一不可；</li><li>一致性复杂度：跨服务事务只能退化为最终一致性；</li><li>联调与治理成本：接口契约管理、灰度、全链路排查难度显著上升；</li><li>团队要求：需要能独立负责端到端的服务 Owner，否则只是把单体乱拆成分布式单体。</li></ul></li></ul><h3 id="_2-5-阶段四-中台-平台化" tabindex="-1">2.5 阶段四：中台 / 平台化 <a class="header-anchor" href="#_2-5-阶段四-中台-平台化" aria-label="Permalink to &quot;2.5 阶段四：中台 / 平台化&quot;">​</a></h3><ul><li><strong>驱动</strong>：组织内多条业务线反复出现同质能力（账号、支付、消息、风控），单点重复建设。</li><li><strong>形态</strong>：把共享能力沉淀为平台服务（技术中台/业务中台），前台业务（如多个 App、多条产品线）复用。</li><li><strong>优势</strong>：避免重复建设、统一标准、数据打通。</li><li><strong>代价</strong>： <ul><li>抽象前置风险：在需求尚不清晰时抽象共享模型，容易造出&quot;没人用对的中台&quot;；</li><li>组织博弈：中台团队与业务团队之间出现&quot;中台化即权力收编&quot;的阻力；</li><li>中台服务变成新的单点与瓶颈：所有前台依赖它，它的变更影响面巨大。</li></ul></li><li><strong>现实教训</strong>：很多中台项目失败不是技术问题，而是把&quot;组织能力复用问题&quot;误当成了&quot;技术平台问题&quot;。中台应自下而上从成熟能力沉淀，而非自上而下先建框架再等业务。</li></ul><h3 id="_2-6-各阶段代价对照表" tabindex="-1">2.6 各阶段代价对照表 <a class="header-anchor" href="#_2-6-各阶段代价对照表" aria-label="Permalink to &quot;2.6 各阶段代价对照表&quot;">​</a></h3><table><thead><tr><th>阶段</th><th>解决的核心问题</th><th>新增的核心代价</th><th>什么信号出现再走下一步</th></tr></thead><tbody><tr><td>单体</td><td>快速验证业务</td><td>协作与扩展瓶颈</td><td>模块耦合、团队冲突、构建变慢</td></tr><tr><td>集群化</td><td>性能与可用性</td><td>中间件运维、有状态改造</td><td>单域代码超过团队维护能力</td></tr><tr><td>微服务</td><td>独立演进与故障隔离</td><td>基础设施、一致性、治理成本</td><td>多条业务线共享能力重复建设</td></tr><tr><td>平台化</td><td>跨线复用</td><td>抽象前置、组织博弈</td><td>数据/团队各自为政无法打通</td></tr></tbody></table><h3 id="_2-7-演进不是必然-停在当前形态" tabindex="-1">2.7 演进不是必然：停在当前形态 <a class="header-anchor" href="#_2-7-演进不是必然-停在当前形态" aria-label="Permalink to &quot;2.7 演进不是必然：停在当前形态&quot;">​</a></h3><p>每一步演进都是&quot;拿复杂度换能力&quot;，而能力当前用不上就是纯亏损。以下情况应明确<strong>停在原地</strong>：</p><ul><li>日活低、变更少的小系统：集群化都不需要，一台高配机器 + 备份即可；</li><li>没有独立团队的单体：拆分后没人能维护独立服务的生命周期；</li><li>业务形态还在剧烈变化：过早拆分/中台化，抽象会被业务反复推翻。</li></ul><p>架构演进是&quot;负债表&quot;管理：技术债与复杂度债要匹配业务能产生的收益。</p><hr><h2 id="三、过度设计的信号与防范" tabindex="-1">三、过度设计的信号与防范 <a class="header-anchor" href="#三、过度设计的信号与防范" aria-label="Permalink to &quot;三、过度设计的信号与防范&quot;">​</a></h2><h3 id="_3-1-什么是过度设计" tabindex="-1">3.1 什么是过度设计 <a class="header-anchor" href="#_3-1-什么是过度设计" aria-label="Permalink to &quot;3.1 什么是过度设计&quot;">​</a></h3><p>过度设计 = 为<strong>当前不存在的复杂度</strong>预先付出成本。它与&quot;前瞻性设计&quot;的区别只有一个判断标准：<strong>这个抽象在可预见的 1~2 个迭代内是否会被用到</strong>。会用到的是前瞻，不会用到的是过度。</p><h3 id="_3-2-典型过度设计信号清单" tabindex="-1">3.2 典型过度设计信号清单 <a class="header-anchor" href="#_3-2-典型过度设计信号清单" aria-label="Permalink to &quot;3.2 典型过度设计信号清单&quot;">​</a></h3><table><thead><tr><th>信号</th><th>典型表现</th><th>潜在后果</th></tr></thead><tbody><tr><td>为低流量系统上微服务</td><td>单体就能支撑，却引入注册中心+网关+分布式事务</td><td>排障链路成倍拉长，发布效率反而下降</td></tr><tr><td>接口三层抽象只有一个实现</td><td>Service 接口 + Impl + 代理层，无第二实现</td><td>每层都是纯转发，徒增跳转与阅读成本</td></tr><tr><td>为不存在的问题做通用化</td><td>提前做多租户、国际化、可插拔规则引擎</td><td>需求方根本不在，代码无人敢删</td></tr><tr><td>用分布式事务解决所有一致性问题</td><td>把能合并的服务硬拆开，再上 Seata/XA</td><td>用最大的复杂度换了本可避免的跨服务问题</td></tr><tr><td>代码层 YAGNI，架构层却&quot;凡事都要留扩展点&quot;</td><td>所有模块都插件化、配置化</td><td>核心逻辑被扩展点切碎，可读性崩塌</td></tr><tr><td>中台化/数据中台先行</td><td>组织没有多条业务线，先搭中台等业务</td><td>平台空转，成为成本中心</td></tr></tbody></table><h3 id="_3-3-必要复杂度-vs-偶然复杂度" tabindex="-1">3.3 必要复杂度 vs 偶然复杂度 <a class="header-anchor" href="#_3-3-必要复杂度-vs-偶然复杂度" aria-label="Permalink to &quot;3.3 必要复杂度 vs 偶然复杂度&quot;">​</a></h3><ul><li><strong>必要复杂度</strong>：业务本身固有的复杂度（如支付必须对账、库存必须防超卖），删不掉，只能建模好；</li><li><strong>偶然复杂度</strong>：由技术选型与实现方式引入的复杂度（如为做微服务引入的注册中心、为做缓存引入的一致性问题）。</li></ul><p>设计者应把精力投入&quot;降低偶然复杂度&quot;：当引入一个技术方案时，先问&quot;它消灭了什么复杂度，又引入了什么新复杂度，净值是否为负&quot;。DDD、微服务、中台在引入前都应过这道&quot;净值&quot;账。</p><h3 id="_3-4-防御过度设计的实践" tabindex="-1">3.4 防御过度设计的实践 <a class="header-anchor" href="#_3-4-防御过度设计的实践" aria-label="Permalink to &quot;3.4 防御过度设计的实践&quot;">​</a></h3><ol><li><strong>YAGNI（You Aren&#39;t Gonna Need It）</strong>：不为&quot;也许将来&quot;写代码，为&quot;现在 + 已排期的下一个迭代&quot;写代码；</li><li><strong>演进式架构</strong>：把&quot;何时拆分、何时加缓存&quot;这类决策延后到信号出现时，用 ADR（架构决策记录）追踪&quot;当时为何不做&quot;；</li><li><strong>最小可行架构（MVA）</strong>：每次架构动作只解决当前最痛的 1~2 个问题，而不是一次到位；</li><li><strong>重构通道</strong>：代码腐化不可怕，可怕的是没有定期还债的通道；把&quot;删无用抽象&quot;当成和&quot;加新功能&quot;一样正当的工作。</li></ol><hr><h2 id="四、示例演进案例" tabindex="-1">四、示例演进案例 <a class="header-anchor" href="#四、示例演进案例" aria-label="Permalink to &quot;四、示例演进案例&quot;">​</a></h2><h3 id="_4-1-案例背景" tabindex="-1">4.1 案例背景 <a class="header-anchor" href="#_4-1-案例背景" aria-label="Permalink to &quot;4.1 案例背景&quot;">​</a></h3><p>一个电商后端，从创业到稳定运营，经历了典型四阶段演进。下表记录每阶段的触发信号与决策依据（重点不是结论，而是&quot;决策是怎么做出来的&quot;）。</p><h3 id="_4-2-阶段一-单体-0-100-万-gmv" tabindex="-1">4.2 阶段一：单体（0 ~ 100 万 GMV） <a class="header-anchor" href="#_4-2-阶段一-单体-0-100-万-gmv" aria-label="Permalink to &quot;4.2 阶段一：单体（0 ~ 100 万 GMV）&quot;">​</a></h3><ul><li><strong>形态</strong>：Spring Boot 单体 + MySQL，模块为 user / order / product / pay 四个 package。</li><li><strong>触发信号</strong>：无，业务尚未验证，团队 5 人。</li><li><strong>主动不做的事</strong>：不拆微服务、不做缓存预热、不上 MQ。理由：业务逻辑全部是简单 CRUD + 一次事务，微服务只会放大问题。</li></ul><h3 id="_4-3-阶段二-单体-集群-缓存-100-万-3000-万-gmv" tabindex="-1">4.3 阶段二：单体 + 集群 + 缓存（100 万 ~ 3000 万 GMV） <a class="header-anchor" href="#_4-3-阶段二-单体-集群-缓存-100-万-3000-万-gmv" aria-label="Permalink to &quot;4.3 阶段二：单体 + 集群 + 缓存（100 万 ~ 3000 万 GMV）&quot;">​</a></h3><ul><li><strong>触发信号</strong>：大促时 DB CPU 飙高、单机 Tomcat 线程池打满、凌晨定时任务拖慢交易。</li><li><strong>动作</strong>：应用无状态化 + 双实例部署 + Nginx 负载均衡；商品详情 Redis 缓存（解决读热点）；订单写库保持不变。</li><li><strong>代价记录</strong>：Session 外置、定时任务加分布式锁防重复执行、缓存一致性引入少量脏读容忍。</li><li><strong>决策复盘</strong>：此时&quot;改单服务&quot;仍只需一次发布，说明没有拆服务的必要。</li></ul><h3 id="_4-4-阶段三-按业务能力拆微服务-3000-万-2-亿-gmv" tabindex="-1">4.4 阶段三：按业务能力拆微服务（3000 万 ~ 2 亿 GMV） <a class="header-anchor" href="#_4-4-阶段三-按业务能力拆微服务-3000-万-2-亿-gmv" aria-label="Permalink to &quot;4.4 阶段三：按业务能力拆微服务（3000 万 ~ 2 亿 GMV）&quot;">​</a></h3><ul><li><strong>触发信号</strong>：订单模块一次改动牵连商品/库存多处回归；交易与后台管理系统互相拖累发布；订单团队与商品团队开始冲突。</li><li><strong>动作</strong>：先按<strong>子域</strong>切出 user / order / product / pay / inventory 五个服务（DDD 边界方法见《DDD领域驱动设计》）；引入注册中心、网关、配置中心；下单链路用&quot;本地消息表/事务消息 + 对账&quot;替代原单体事务（取舍方法见《微服务架构与拆分》）。</li><li><strong>代价记录</strong>：新增基础设施运维；下单从强一致变为最终一致；联调成本上升，靠契约测试与统一 Trace ID 缓解。</li></ul><h3 id="_4-5-阶段四-中台化尝试与反思" tabindex="-1">4.5 阶段四：中台化尝试与反思 <a class="header-anchor" href="#_4-5-阶段四-中台化尝试与反思" aria-label="Permalink to &quot;4.5 阶段四：中台化尝试与反思&quot;">​</a></h3><ul><li><strong>触发信号</strong>：公司开第二条业务线（社区团购），发现账号、支付、消息、风控都要重写一遍。</li><li><strong>动作</strong>：把<strong>已成熟运行两年以上</strong>的支付、账号沉淀为平台服务，供两条业务线共用；<strong>没有</strong>把尚未稳定的社区团购业务逻辑提前抽象进中台。</li><li><strong>反思记录</strong>：沉淀的是&quot;验证过的能力&quot;而非&quot;猜出来的需求&quot;；中台团队按平台服务设 Owner，不设大一统架构组。</li></ul><h3 id="_4-6-演进决策复盘表" tabindex="-1">4.6 演进决策复盘表 <a class="header-anchor" href="#_4-6-演进决策复盘表" aria-label="Permalink to &quot;4.6 演进决策复盘表&quot;">​</a></h3><table><thead><tr><th>决策点</th><th>当时不做（做了什么）</th><th>后来做（触发信号）</th><th>教训</th></tr></thead><tbody><tr><td>首版是否微服务</td><td>单体</td><td>业务验证后才按子域拆</td><td>信号驱动，不赶潮流</td></tr><tr><td>是否提前中台化</td><td>先各自建设</td><td>第二条业务线出现且能力成熟后</td><td>抽象不能早于使用方</td></tr><tr><td>是否每步都上 MQ</td><td>直连调用</td><td>出现削峰/解耦刚需后</td><td>新技术要有明确买单人</td></tr></tbody></table><hr><h2 id="五、如何落地与常见误区" tabindex="-1">五、如何落地与常见误区 <a class="header-anchor" href="#五、如何落地与常见误区" aria-label="Permalink to &quot;五、如何落地与常见误区&quot;">​</a></h2><h3 id="_5-1-用-adr-记录架构决策" tabindex="-1">5.1 用 ADR 记录架构决策 <a class="header-anchor" href="#_5-1-用-adr-记录架构决策" aria-label="Permalink to &quot;5.1 用 ADR 记录架构决策&quot;">​</a></h3><p>ADR（Architecture Decision Record）是防止&quot;架构拍脑袋 + 后人不知道为什么&quot;的最小工具，每条 4 节即可：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;"># ADR-007：订单服务拆分决策</span></span>
<span class="line"><span style="color:#e1e4e8;"></span></span>
<span class="line"><span style="color:#e1e4e8;">状态：已接受</span></span>
<span class="line"><span style="color:#e1e4e8;">背景：订单模块频繁改动牵连商品回归，发布互相阻塞。</span></span>
<span class="line"><span style="color:#e1e4e8;">决策：按子域拆出 order 服务，下单改为本地消息表 + 对账的最终一致。</span></span>
<span class="line"><span style="color:#e1e4e8;">后果：新增 MQ 依赖与对账任务；换取独立发布与故障隔离。</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;"># ADR-007：订单服务拆分决策</span></span>
<span class="line"><span style="color:#24292e;"></span></span>
<span class="line"><span style="color:#24292e;">状态：已接受</span></span>
<span class="line"><span style="color:#24292e;">背景：订单模块频繁改动牵连商品回归，发布互相阻塞。</span></span>
<span class="line"><span style="color:#24292e;">决策：按子域拆出 order 服务，下单改为本地消息表 + 对账的最终一致。</span></span>
<span class="line"><span style="color:#24292e;">后果：新增 MQ 依赖与对账任务；换取独立发布与故障隔离。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>有了 ADR，&quot;为什么不拆&quot;&quot;为什么上 MQ&quot;在几个月后仍可追溯，避免重复争论与推倒重来。</p><h3 id="_5-2-常见误区清单" tabindex="-1">5.2 常见误区清单 <a class="header-anchor" href="#_5-2-常见误区清单" aria-label="Permalink to &quot;5.2 常见误区清单&quot;">​</a></h3><table><thead><tr><th>误区</th><th>正解</th></tr></thead><tbody><tr><td>把架构演进当升级打怪，一路走到微服务</td><td>每个阶段都是可选停留点，以信号为准</td></tr><tr><td>用微服务解决性能问题</td><td>性能问题优先用集群/缓存/读写分离解决</td></tr><tr><td>用中台解决组织协同问题</td><td>组织问题先用组织手段解决，中台只是放大器</td></tr><tr><td>为代码复用而合并边界</td><td>架构层隔离优先于复用</td></tr><tr><td>没有 ADR，架构决策靠口口相传</td><td>每个决策留痕，含&quot;当时为什么不这么做&quot;</td></tr><tr><td>重构只加不删</td><td>定期清理无用抽象与过期扩展点</td></tr></tbody></table><h3 id="_5-3-落地检查清单" tabindex="-1">5.3 落地检查清单 <a class="header-anchor" href="#_5-3-落地检查清单" aria-label="Permalink to &quot;5.3 落地检查清单&quot;">​</a></h3><ul><li>[ ] 当前架构形态与团队规模、流量、业务复杂度匹配；</li><li>[ ] 能说出最近一次演进是被哪个信号触发的；</li><li>[ ] 架构层改动的波及面是否遵循 SRP（一次变更尽量命中一个边界）；</li><li>[ ] 领域/核心代码不依赖具体中间件 API（DIP 是否成立）；</li><li>[ ] 关键演进决策都有 ADR 记录；</li><li>[ ] 没有为未来 1~2 个迭代用不上的能力预留抽象。</li></ul>`,82)]))}const c=a(e,[["render",d]]);export{p as __pageData,c as default};
